102	inline FormatShape InferShapeOfNDHWC(c10::IntArrayRef arrayDims, size_t itemsize)
103	{
104	    if (arrayDims.size() < 5) {
105	        AT_ERROR("dim (", arrayDims, ") cannot convert to NDHWC");
106	    }
107	    FormatShape formatShape;
108	    formatShape.resize(5);
109	    formatShape[0] = arrayDims[0];
110	    formatShape[1] = arrayDims[2];
111	    formatShape[2] = arrayDims[3];
112	    formatShape[3] = arrayDims[4];
113	    formatShape[4] = arrayDims[1];
114	    return formatShape;
115	}
116	
117	inline FormatShape InferShapeOfNCDHW(c10::IntArrayRef arrayDims, size_t itemsize)
118	{
119	    if (arrayDims.size() < 5) {
120	        AT_ERROR("dim (", arrayDims, ") cannot convert to NCDHW");
121	    }
122	    FormatShape formatShape;
123	    formatShape.resize(5);
124	    formatShape[0] = arrayDims[0];
125	    formatShape[1] = arrayDims[1];
126	    formatShape[2] = arrayDims[2];
127	    formatShape[3] = arrayDims[3];
128	    formatShape[4] = arrayDims[4];
129	    return formatShape;
130	}
131	
132	inline FormatShape InferShapeOfNDC1HWC0(c10::IntArrayRef arrayDims, size_t itemsize)
133	{
134	    if (arrayDims.size() < 5) {
135	        AT_ERROR("dim (", arrayDims, ") cannot convert to NDC1HWC0");
136	    }
137	    FormatShape formatShape;
138	    formatShape.resize(6);
139	    formatShape[0] = arrayDims[0];
140	    formatShape[1] = arrayDims[2];
141	    formatShape[2] = (arrayDims[1] + BLOCKSIZE - 1) / BLOCKSIZE;
142	    formatShape[3] = arrayDims[3];
143	    formatShape[4] = arrayDims[4];
144	    formatShape[5] = BLOCKSIZE;
145	    return formatShape;
146	}
