148	inline FormatShape InferShapeOfFZ3D(c10::IntArrayRef arrayDims, size_t itemsize)
149	{
150	    if (arrayDims.size() < 5) {
151	        AT_ERROR("dim (", arrayDims, ") cannot convert to FZ_3D");
152	    }
153	
154	    int64_t dim1 = arrayDims[2];
155	    int64_t dim2 = (arrayDims[1] + BLOCKSIZE - 1) / BLOCKSIZE;
156	    int64_t dim3 = arrayDims[3];
157	    int64_t dim4 = arrayDims[4];
158	    int64_t dim5 = (arrayDims[0] + BLOCKSIZE - 1) / BLOCKSIZE;
159	    int64_t dim6 = BLOCKSIZE;
160	    int64_t dim7 = BLOCKSIZE;
161	
162	    FormatShape formatShape;
163	    formatShape.resize(4);
164	    formatShape[0] = dim1 * dim2 * dim3 * dim4;
165	    formatShape[1] = dim5;
166	    formatShape[2] = dim6;
167	    formatShape[3] = dim7;
168	    return formatShape;
169	}
