171	inline FormatShape InferShapeofNCHW(c10::IntArrayRef dims, size_t itemsize)
172	{
173	    if (dims.size() < 5) {
174	        return InferShapeLessTo4(dims, itemsize);
175	    } else {
176	        return InferShapeofND(dims, itemsize);
177	    }
178	}
