180	inline FormatShape InferShapeofND(c10::IntArrayRef dims, size_t itemsize)
181	{
182	    FormatShape res;
183	    res.resize(dims.size());
184	    for (size_t j = 0; j < dims.size(); j++) {
185	        res[j] = dims[j];
186	    }
187	    return res;
188	}
