190	inline FormatShape InferShape4To5(c10::IntArrayRef dims, size_t itemsize)
191	{
192	    FormatShape res;
193	    res.resize(5);
194	    if (dims.size() < 4) {
195	        ASCEND_LOGD("infershape4to5 but input dim < 4");
196	        return InferShape4To5(InferShapeLessTo4(dims, itemsize), itemsize);
197	    } else if (dims.size() > 4) {
198	        ASCEND_LOGE("infershape4to5 but input dim > 4");
199	    }
200	    res[0] = dims[0];
201	    res[1] = (dims[1] + 15) / 16;
202	    res[2] = dims[2];
203	    res[3] = dims[3];
204	    res[4] = BLOCKSIZE;
205	    return res;
206	}
