208	inline FormatShape InferShapeofNHWC(c10::IntArrayRef dims, size_t itemsize)
209	{
210	    AT_ASSERT(dims.size() == 4, "input dim should be equal to 4 when InferShapeofNHWC");
211	    return FormatShape(dims.begin(), dims.end());
212	}
