214	inline FormatShape InferShapeNDToNZ(c10::IntArrayRef dims, size_t itemsize)
215	{
216	    FormatShape res;
217	    // sum(keepdim = false) may make tensor dim = 0
218	    FormatShape dim;
219	    for (size_t i = 0; i < dims.size(); i++) {
220	        dim.emplace_back(dims[i]);
221	    }
222	
223	    // this action will move to GuessStorageSizeWhenConvertFormat
224	    if (dim.size() == 0) {
225	        dim.emplace_back(1);
226	    }
227	    if (dim.size() == 1) {
228	        dim.emplace_back(1);
229	    }
230	
231	    size_t i = 0;
232	    for (; i < dim.size() - 2; i++) {
233	        res.emplace_back(dim[i]);
234	    }
235	
236	    AT_ASSERT(itemsize != 0, "dtype itemsize should not be 0");
237	
238	    // float32 will cast to float16
239	    auto itemsize_ = (itemsize > 2) ? 2 : itemsize;
240	    auto lastSize = BLOCKBYTES / itemsize_;
241	    res.emplace_back((dim[i + 1] + lastSize - 1) / lastSize);
242	    res.emplace_back((dim[i] + BLOCKSIZE - 1) / BLOCKSIZE);
243	    res.emplace_back(BLOCKSIZE);
244	    res.emplace_back(lastSize);
245	
246	    return res;
247	}
248	
249	inline FormatShape InferShapeNDToZ(c10::IntArrayRef dims, size_t itemsize)
250	{
251	    FormatShape res;
252	    if (dims.size() < 4) {
253	        return InferShapeNDToZ(InferShapeLessTo4(dims, itemsize), itemsize);
254	    }
255	
256	    res.emplace_back((dims[1] + 15) / BLOCKSIZE * dims[2] * dims[3]);
257	    res.emplace_back((dims[0] + 15) / BLOCKSIZE);
258	    res.emplace_back(BLOCKSIZE);
259	    res.emplace_back(BLOCKSIZE);
260	
261	    return res;
262	}
263	
264	inline FormatShape InferShapeLessTo4(c10::IntArrayRef arrayDims, size_t itemsize)
265	{
266	    FormatShape formatShape;
267	    formatShape.resize(4);
268	    AT_ASSERT(arrayDims.size() <= 4, "input dim > 4 when InferShapeLessTo4");
269	    switch (arrayDims.size()) {
270	        case 0:
271	            formatShape[0] = 1;
272	            formatShape[1] = 1;
273	            formatShape[2] = 1;
274	            formatShape[3] = 1;
275	            break;
276	        case 1:  // RESHAPE_TYPE_C
277	            formatShape[0] = 1;
278	            formatShape[1] = arrayDims[0];
279	            formatShape[2] = 1;
280	            formatShape[3] = 1;
281	            break;
282	        case 2:  // RESHAPE_TYPE_CH
283	            formatShape[0] = 1;
284	            formatShape[1] = arrayDims[0];
285	            formatShape[2] = arrayDims[1];
286	            formatShape[3] = 1;
287	            break;
288	        case 3:  // RESHAPE_TYPE_CHW
289	            formatShape[0] = 1;
290	            formatShape[1] = arrayDims[0];
291	            formatShape[2] = arrayDims[1];
292	            formatShape[3] = arrayDims[2];
293	            break;
294	        case 4:
295	            formatShape[0] = arrayDims[0];
296	            formatShape[1] = arrayDims[1];
297	            formatShape[2] = arrayDims[2];
298	            formatShape[3] = arrayDims[3];
299	            break;
300	        default:
301	            AT_ERROR("dims of NCHW shape should not be greater than 4, which is ", arrayDims.size());
302	    }
303	    return formatShape;
304	}
