473	{
474	    int end = s.find(del);
475	    std::vector<std::string> path_list;
476	    while (end != -1) {
477	        path_list.push_back(s.substr(0, end));
478	        s.erase(s.begin(), s.begin() + end + 1);
479	        end = s.find(del);
480	    }
481	    path_list.push_back(s);
482	    return path_list;
483	}
