619	#define GET_OP_API_FUNC(apiName) \
620	  reinterpret_cast<_##apiName>(GetOpApiFuncAddr(#apiName))
621	
622	inline void *GetOpApiFuncAddr(const char *apiName)
623	{
624	    if (!g_custom_lib_path.empty()) {
625	        for (auto &it : g_custom_lib_path) {
626	            auto cust_opapi_lib = real_path(it + "/" + GetCustOpApiLibName());
627	            if (cust_opapi_lib.empty()) {
628	                continue;
629	            }
630	            auto custOpApiHandler = GetOpApiLibHandler(cust_opapi_lib.c_str());
631	            if (custOpApiHandler != nullptr) {
632	                auto funcAddr =
633	                    GetOpApiFuncAddrInLib(custOpApiHandler, GetCustOpApiLibName(), apiName);
634	                if (funcAddr != nullptr) {
635	                    ASCEND_LOGI("%s is found in %s.", apiName, cust_opapi_lib.c_str());
636	                    return funcAddr;
637	                }
638	            }
639	        }
640	        ASCEND_LOGI("%s is not in custom lib.", apiName);
641	    }
642	
643	    if (!g_default_custom_lib_path.empty()) {
644	        for (auto &it : g_default_custom_lib_path) {
645	            auto default_cust_opapi_lib = real_path(it + "/" + GetCustOpApiLibName());
646	            if (default_cust_opapi_lib.empty()) {
647	                continue;
648	            }
649	            auto custOpApiHandler = GetOpApiLibHandler(default_cust_opapi_lib.c_str());
650	            if (custOpApiHandler != nullptr) {
651	                auto funcAddr =
652	                    GetOpApiFuncAddrInLib(custOpApiHandler, GetCustOpApiLibName(), apiName);
653	                if (funcAddr != nullptr) {
654	                    ASCEND_LOGI("%s is found in %s.", apiName, default_cust_opapi_lib.c_str());
655	                    return funcAddr;
656	                }
657	            }
658	        }
659	        ASCEND_LOGI("%s is not in default custom lib.", apiName);
660	    }
661	
662	    GET_OP_API_FUNC_FROM_FEATURE_LIB(opapiMathHandler, "libopapi_math.so", apiName);
663	    GET_OP_API_FUNC_FROM_FEATURE_LIB(opapiNnHandler, "libopapi_nn.so", apiName);
664	    GET_OP_API_FUNC_FROM_FEATURE_LIB(opapiCvHandler, "libopapi_cv.so", apiName);
665	    GET_OP_API_FUNC_FROM_FEATURE_LIB(opapiTransformerHandler, "libopapi_transformer.so", apiName);
666	    GET_OP_API_FUNC_FROM_FEATURE_LIB(opapiLegacyHandler, "libopapi_legacy.so", apiName);
667	
668	    static auto opApiHandler = GetOpApiLibHandler(GetOpApiLibName());
669	    if (opApiHandler != nullptr) {
670	        auto funcAddr = GetOpApiFuncAddrInLib(opApiHandler, GetOpApiLibName(), apiName);
671	        if (funcAddr != nullptr) {
672	            return funcAddr;
673	        }
674	    }
675	    return GetOpApiFuncAddrFromFeatureLib(apiName);
676	}
