689	    int64_t value = *(int64_t *)aclInput->data_ptr();
690	    c10::Scalar scalar(value);
691	    expScalar = scalar;
692	  } else if (aclInput->scalar_type() == at::ScalarType::Float) {
693	    float value = *(float *)aclInput->data_ptr();
694	    c10::Scalar scalar(value);
695	    expScalar = scalar;
696	  } else if (aclInput->scalar_type() == at::ScalarType::Int) {
697	    int value = *(int *)aclInput->data_ptr();
698	    c10::Scalar scalar(value);
699	    expScalar = scalar;
700	  } else if (aclInput->scalar_type() == at::ScalarType::Half) {
701	    c10::Half value = *(c10::Half *)aclInput->data_ptr();
702	    c10::Scalar scalar(value);
703	    expScalar = scalar;
704	  } else if (aclInput->scalar_type() == at::ScalarType::Bool) {
705	    int8_t value = *(int8_t *)aclInput->data_ptr();
706	    c10::Scalar scalar(value);
707	    expScalar = scalar;
708	  } else if (aclInput->scalar_type() == at::ScalarType::ComplexDouble) {
709	    c10::complex<double> value = *(c10::complex<double> *)aclInput->data_ptr();
710	    c10::Scalar scalar(value);
711	    expScalar = scalar;
712	  } else if (aclInput->scalar_type() == at::ScalarType::ComplexFloat) {
713	    c10::complex<float> value = *(c10::complex<float> *)aclInput->data_ptr();
714	    c10::Scalar scalar(value);
715	    expScalar = scalar;
716	  } else if (aclInput->scalar_type() == at::ScalarType::BFloat16) {
717	    c10::BFloat16 value = *(c10::BFloat16 *)aclInput->data_ptr();
718	    c10::Scalar scalar(value);
719	    expScalar = scalar;
720	  }
721	  return expScalar;
722	}
