738	static bool IsOpInputBaseFormatCommon(const at::Tensor &at_tensor)
739	{
740	  if (!torch_npu::utils::is_npu(at_tensor)) {
741	    return true;
742	  }
743	  const auto format = static_cast<NPUStorageImpl *>(at_tensor.storage().unsafeGetStorageImpl())->npu_desc_.npu_format_;
744	  return (format == ACL_FORMAT_ND) || (format == ACL_FORMAT_NCHW) || (format == ACL_FORMAT_NHWC) ||
745	      (format == ACL_FORMAT_NCDHW);
746	}
