748	static bool IsBaseFormatTypeCommon(aclFormat format)
749	{
750	    std::unordered_map<aclFormat, AclFormatInfoShape> info = InitializeInfo();
751	    const auto &itr = info.find(format);
752	    if (itr == info.end()) {
753	        return ACL_FORMAT_ND;
754	    }
755	    return itr->second.baseFormat == format;
756	}
