758	inline aclTensor *ConvertType(const at::Tensor &at_tensor)
759	{
760	  static const auto aclCreateTensor = GET_OP_API_FUNC(aclCreateTensor);
761	  if (aclCreateTensor == nullptr) {
762	    return nullptr;
763	  }
764	
765	  if (!at_tensor.defined()) {
766	    return nullptr;
767	  }
768	  at::ScalarType scalar_data_type = at_tensor.scalar_type();
769	  aclDataType acl_data_type =
770	      kATenScalarTypeToAclDataTypeTable[static_cast<int64_t>(scalar_data_type)];
771	  TORCH_CHECK(
772	      acl_data_type != ACL_DT_UNDEFINED,
773	      std::string(c10::toString(scalar_data_type)) + " has not been supported")
774	  c10::SmallVector<int64_t, SIZE> storageDims;
775	
776	  const auto dimNum = at_tensor.sizes().size();
777	  aclFormat format = ACL_FORMAT_ND;
778	  if (!IsOpInputBaseFormatCommon(at_tensor)) {
779	    format = static_cast<NPUStorageImpl *>(at_tensor.storage().unsafeGetStorageImpl())->npu_desc_.npu_format_;
780	    if (acl_data_type != ACL_STRING) {
781	        TORCH_CHECK(at_tensor.itemsize() > 0, "the itemsize of tensor must be greater than 0.");
782	        storageDims = static_cast<NPUStorageImpl *>(
783	                          at_tensor.storage().unsafeGetStorageImpl())
784	                          ->npu_desc_.storage_sizes_;
785	    }
786	  } else {
787	    switch (dimNum) {
788	        case 3:
789	            format = ACL_FORMAT_NCL;
790	            break;
791	        case 4:
792	            format = ACL_FORMAT_NCHW;
793	            break;
794	        case 5:
795	            format = ACL_FORMAT_NCDHW;
796	            break;
797	        default:
798	            format = ACL_FORMAT_ND;
799	    }
800	    if (acl_data_type != ACL_STRING) {
801	        TORCH_CHECK(at_tensor.itemsize() > 0, "the itemsize of tensor must be greater than 0.");
802	        storageDims.push_back(at_tensor.storage().nbytes() / at_tensor.itemsize());
803	    }
804	  }
805	
806	  if (at_tensor.unsafeGetTensorImpl()->is_wrapped_number()) {
807	    // no need this ConvertTensorToScalar
808	    c10::Scalar expScalar = at_tensor.item();
809	    at::Tensor aclInput = CopyScalarToDevice(expScalar, scalar_data_type);
810	    return aclCreateTensor(aclInput.sizes().data(), aclInput.sizes().size(),
811	                           acl_data_type, aclInput.strides().data(),
812	                           aclInput.storage_offset(), format,
813	                           storageDims.data(), storageDims.size(),
814	                           const_cast<void *>(aclInput.storage().data()));
815	  }
816	
817	  auto acl_tensor = aclCreateTensor(
818	      at_tensor.sizes().data(), at_tensor.sizes().size(), acl_data_type,
819	      at_tensor.strides().data(), at_tensor.storage_offset(), format,
820	      storageDims.data(), storageDims.size(),
821	      const_cast<void *>(at_tensor.storage().data()));
822	  return acl_tensor;
823	}
