1005	inline aclTensor *ConvertType(const TensorWrapper &tensor_r)
1006	{
1007	    static const auto aclCreateTensor = GET_OP_API_FUNC(aclCreateTensor);
1008	    if (aclCreateTensor == nullptr) {
1009	        return nullptr;
1010	    }
1011	
1012	    const at::Tensor &at_tensor = tensor_r.tensor_;
1013	
1014	    if (!at_tensor.defined()) {
1015	        return nullptr;
1016	    }
1017	    TORCH_CHECK(torch_npu::utils::is_npu(at_tensor),
1018	        "Expected all tensors to be on the same device. "
1019	        "Expected NPU tensor, please check whether the input tensor device is correct.");
1020	
1021	    aclDataType acl_data_type = tensor_r.dtype;
1022	    c10::SmallVector<int64_t, MAX_DIM_NUM> storageDims;
1023	    c10::SmallVector<int64_t, MAX_DIM_NUM> wrapperStride = array_to_small_vector(at_tensor.strides());
1024	    c10::SmallVector<int64_t, MAX_DIM_NUM> wrapperShape = array_to_small_vector(at_tensor.sizes());
1025	
1026	    const auto dimNum = at_tensor.sizes().size();
1027	    aclFormat format = ACL_FORMAT_ND;
1028	    if (!IsOpInputBaseFormatCommon(at_tensor)) {
1029	        format = static_cast<NPUStorageImpl *>(at_tensor.storage().unsafeGetStorageImpl())->npu_desc_.npu_format_;
1030	        // if acl_data_type is ACL_STRING, storageDims is empty.
1031	        if (acl_data_type != ACL_STRING) {
1032	            TORCH_CHECK(at_tensor.itemsize() > 0, "the itemsize of tensor must be greater than 0.");
1033	            storageDims = static_cast<NPUStorageImpl *>(
1034	                              at_tensor.storage().unsafeGetStorageImpl())
1035	                              ->npu_desc_.storage_sizes_;
1036	        }
1037	    } else {
1038	        switch (dimNum) {
1039	            case NCL_DIM_NUM:
1040	                format = ACL_FORMAT_NCL;
1041	                break;
1042	            case NCHW_DIM_NUM:
