1427	inline aclTensor *ConvertTypeV2(TensorStructPtr at_tensor)
1428	{
1429	    static const auto aclCreateTensor = GET_OP_API_FUNC(aclCreateTensor);
1430	    if (aclCreateTensor == nullptr) {
1431	        return nullptr;
1432	    }
1433	
1434	    if (at_tensor == nullptr) {
1435	        return nullptr;
1436	    }
1437	    aclDataType acl_data_type = (*at_tensor).acl_type;
1438	    c10::SmallVector<int64_t, MAX_DIM_NUM> storageDims;
1439	
1440	    const auto dimNum = (*at_tensor).sizes.size();
1441	    aclFormat format = ACL_FORMAT_ND;
1442	    if (!IsBaseFormatTypeCommon((*at_tensor).acl_format)) {
1443	        format = (*at_tensor).acl_format;
1444	        // if acl_data_type is ACL_STRING, storageDims is empty.
1445	        if (acl_data_type != ACL_STRING) {
1446	            TORCH_CHECK((*at_tensor).itemsize > 0, "the itemsize of tensor must be greater than 0.");
1447	            storageDims = (*at_tensor).storage_sizes;
1448	        }
1449	    } else {
1450	        switch (dimNum) {
1451	            case NCL_DIM_NUM:
1452	                format = ACL_FORMAT_NCL;
1453	                break;
1454	            case NCHW_DIM_NUM:
1455	                format = ACL_FORMAT_NCHW;
1456	                break;
1457	            case NCDHW_DIM_NUM:
1458	                format = ACL_FORMAT_NCDHW;
1459	                break;
1460	            default:
1461	                format = ACL_FORMAT_ND;
1462	        }
1463	        // if acl_data_type is ACL_STRING, storageDims is empty.
1464	        if (acl_data_type != ACL_STRING) {
1465	            TORCH_CHECK((*at_tensor).itemsize > 0, "the itemsize of tensor must be greater than 0.");
1466	            storageDims.push_back((*at_tensor).nbytes / (*at_tensor).itemsize);
1467	        }
1468	    }
1469	
1470	    auto acl_tensor = aclCreateTensor(
1471	        (*at_tensor).sizes.data(), (*at_tensor).sizes.size(), acl_data_type, (*at_tensor).strides.data(),
1472	        (*at_tensor).storage_offset, format, storageDims.data(), storageDims.size(), (*at_tensor).data_ptr);
1473	    return acl_tensor;
1474	}
