1778	    do {                                                                                                               \
1779	        static const auto getWorkspaceSizeFuncAddr = GetOpApiFuncAddr(#aclnn_api "GetWorkspaceSize");                  \
1780	        static const auto opApiFuncAddr = GetOpApiFuncAddr(#aclnn_api);                                                \
1781	        static const auto initMemAddr = GetOpApiFuncAddr("InitHugeMemThreadLocal");                                    \
1782	        static const auto unInitMemAddr = GetOpApiFuncAddr("UnInitHugeMemThreadLocal");                                \
1783	        static const auto releaseMemAddr = GetOpApiFuncAddr("ReleaseHugeMem");                                         \
1784	        static const auto initPTACacheThreadLocalAddr = GetOpApiFuncAddr("InitPTACacheThreadLocal");                   \
1785	        static const auto setPTAHashKeyAddr = GetOpApiFuncAddr("SetPTAHashKey");                                       \
1786	        TORCH_CHECK(getWorkspaceSizeFuncAddr != nullptr && opApiFuncAddr != nullptr, #aclnn_api, " or ",               \
1787	                    #aclnn_api "GetWorkspaceSize", " not in ", GetOpApiLibName(), ", or ", GetOpApiLibName(),          \
1788	                    "not found.");                                                                                     \
1789	        auto acl_stream = c10_npu::getCurrentNPUStream().stream(false);                                                \
1790	        aclOpExecutor *executor = nullptr;                                                                             \
1791	        aclOpExecutor **executor_addr = &executor;                                                                     \
1792	        InitHugeMemThreadLocal initMemFunc = reinterpret_cast<InitHugeMemThreadLocal>(initMemAddr);                    \
1793	        UnInitHugeMemThreadLocal unInitMemFunc = reinterpret_cast<UnInitHugeMemThreadLocal>(unInitMemAddr);            \
1794	        InitPTACacheThreadLocal initPTACacheThreadLocalFunc =                                                          \
1795	            reinterpret_cast<InitPTACacheThreadLocal>(initPTACacheThreadLocalAddr);                                    \
1796	        SetPTAHashKey setPTAHashKeyFunc = reinterpret_cast<SetPTAHashKey>(setPTAHashKeyAddr);                          \
1797	        if (initPTACacheThreadLocalFunc && setPTAHashKeyFunc) {                                                        \
1798	            initPTACacheThreadLocalFunc();                                                                             \
1799	            setPTAHashKeyFunc(0);                                                                                      \
1800	        }                                                                                                              \
